export async function gate({ referenceDir, submissionDir }) {
  const fs = await import('node:fs');
  const path = await import('node:path');
  const { spawn } = await import('node:child_process');
  const crypto = await import('node:crypto');
  const submissionFile = path.join(submissionDir, 'answer.mjs');
  if (!fs.existsSync(submissionFile)) {
    return { accept: false, reason: 'missing answer.mjs' };
  }
  function expectedDedupe(arr) {
    const out = [];
    for (let i = 0; i < arr.length; i++) {
      if (i === 0 || arr[i] !== arr[i - 1]) out.push(arr[i]);
    }
    return out;
  }
  function eq(a, b) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i]) return false;
    }
    return true;
  }
  const tests = [];
  function add(arr) { tests.push(arr); }
  function exhaustive(minVal, maxVal, maxLen) {
    const acc = [];
    function rec(remaining, start) {
      if (remaining === 0) {
        add(acc.slice());
        return;
      }
      for (let v = start; v <= maxVal; v++) {
        acc.push(v);
        rec(remaining - 1, v);
        acc.pop();
      }
    }
    add([]);
    for (let len = 1; len <= maxLen; len++) rec(len, minVal);
  }
  exhaustive(-8, 8, 4);
  exhaustive(-4, 3, 5);
  exhaustive(-5, 5, 4);
  for (let a = -4; a <= 3; a++) {
    for (let b = a; b <= 3; b++) {
      for (let c = b; c <= 3; c++) {
        for (let d = c; d <= 3; d++) {
          add([a, b, c, d]);
        }
      }
    }
  }
  for (let a = -4; a <= 3; a++) {
    for (let b = a; b <= 3; b++) {
      for (let c = b; c <= 3; c++) {
        add([a, b, c]);
        add([a, a, b, c]);
        add([a, b, b, c]);
        add([a, b, c, c]);
      }
    }
  }
  for (let len = 0; len <= 80; len++) {
    const vs = [-8, -4, -3, -2, -1, 0, 1, 2, 3, 4, 7, 9];
    for (let i = 0; i < vs.length; i++) {
      const v = vs[i];
      const arr = [];
      for (let j = 0; j < len; j++) arr.push(v);
      add(arr);
    }
  }
  const pairA = [-5, -4, -3, -2, -1, 0, 1, 2, 3];
  const pairB = [-4, -3, -2, -1, 0, 1, 2, 3, 4];
  for (let i = 0; i < pairA.length; i++) {
    for (let j = 0; j < pairB.length; j++) {
      const a = pairA[i];
      const b = pairB[j];
      if (a > b) continue;
      for (let n = 2; n <= 16; n++) {
        for (let k = 0; k <= n; k++) {
          const arr = [];
          for (let t = 0; t < k; t++) arr.push(a);
          for (let t = 0; t < n - k; t++) arr.push(b);
          add(arr);
        }
      }
    }
  }
  const tvs = [-4, -3, -1, 0, 1, 2, 3];
  for (let i = 0; i < tvs.length; i++) {
    for (let j = i; j < tvs.length; j++) {
      for (let k = j; k < tvs.length; k++) {
        const a = tvs[i], b = tvs[j], c = tvs[k];
        for (let x = 1; x <= 3; x++) {
          for (let y = 1; y <= 3; y++) {
            for (let z = 1; z <= 3; z++) {
              const arr = [];
              for (let t = 0; t < x; t++) arr.push(a);
              for (let t = 0; t < y; t++) arr.push(b);
              for (let t = 0; t < z; t++) arr.push(c);
              add(arr);
            }
          }
        }
      }
    }
  }
  for (let start = -6; start <= 6; start++) {
    for (let len = 1; len <= 12; len++) {
      const arr = [];
      for (let i = 0; i < len; i++) arr.push(start + i);
      add(arr);
    }
  }
  add([5]);
  add([1, 2, 3]);
  add([4, 4, 4, 4]);
  add([1, 1, 2, 3]);
  add([1, 2, 3, 3]);
  add([-3, -3, -1, 0, 0, 2]);
  add([1, 1, 2, 2, 3, 3]);
  add([-10, -10, -5, 0, 0, 0, 5, 5, 10]);
  add([-4, -4, -4, 3]);
  add([-4, -4, 3, 3]);
  add([-4, 3, 3, 3]);
  add([-4, -3, -3, 3]);
  add([-4, -4, 0, 3]);
  add([0, 0, 0, 0]);
  add([-4, -4, -4, -4]);
  add([3, 3, 3, 3]);
  add([-4, -3, -2, -1]);
  add([-4, -4, -3, -3]);
  add([-4, -2, -2, 3]);
  add([-1, -1, 2, 2]);
  add([-4, -4, -3, 3]);
  add([-4, 0, 0, 3]);
  add([-4, -1, -1, 3]);
  add([2, 2, 2, 3]);
  add([-4, -4, 2, 2]);
  const nl = String.fromCharCode(10);
  const runnerSrc = [
    "import fs from 'node:fs';",
    "import { pathToFileURL } from 'node:url';",
    "const submissionPath = process.argv[2];",
    "const inputPath = process.argv[3];",
    "const outputPath = process.argv[4];",
    "const inputs = JSON.parse(fs.readFileSync(inputPath, 'utf8'));",
    "const mod = await import(pathToFileURL(submissionPath).href);",
    "if (typeof mod.dedupeSorted !== 'function') process.exit(2);",
    "const outputs = [];",
    "for (let i = 0; i < inputs.length; i++) {",
    "  const input = inputs[i];",
    "  const copy = Array.isArray(input) ? input.slice() : input;",
    "  let result;",
    "  try { result = mod.dedupeSorted(copy); } catch (e) { process.exit(3); }",
    "  outputs.push(result);",
    "}",
    "fs.writeFileSync(outputPath, JSON.stringify(outputs));"
  ].join(nl);
  const id = crypto.randomBytes(16).toString('hex');
  const runnerPath = path.join(referenceDir, 'run-' + id + '.mjs');
  const inputPath = path.join(referenceDir, 'in-' + id + '.json');
  const outputPath = path.join(referenceDir, 'out-' + id + '.json');
  fs.writeFileSync(runnerPath, runnerSrc);
  fs.writeFileSync(inputPath, JSON.stringify(tests));
  const runResult = await new Promise(function (resolve) {
    const child = spawn(process.execPath, [runnerPath, submissionFile, inputPath, outputPath], { stdio: ['ignore', 'ignore', 'ignore'] });
    let settled = false;
    const timer = setTimeout(function () {
      if (!settled) {
        settled = true;
        try { child.kill('SIGKILL'); } catch (e) {}
        resolve({ timeout: true, code: null });
      }
    }, 20000);
    child.on('error', function () {
      if (!settled) {
        settled = true;
        clearTimeout(timer);
        resolve({ timeout: false, code: -1 });
      }
    });
    child.on('close', function (code) {
      if (!settled) {
        settled = true;
        clearTimeout(timer);
        resolve({ timeout: false, code: code });
      }
    });
  });
  let outputs = null;
  let err = null;
  if (runResult.timeout) err = 'timeout';
  else if (runResult.code !== 0) err = 'nonzero';
  else if (!fs.existsSync(outputPath)) err = 'noout';
  else {
    try { outputs = JSON.parse(fs.readFileSync(outputPath, 'utf8')); }
    catch (e) { err = 'badjson'; }
  }
  try { fs.unlinkSync(runnerPath); } catch (e) {}
  try { fs.unlinkSync(inputPath); } catch (e) {}
  try { fs.unlinkSync(outputPath); } catch (e) {}
  if (err) {
    return { accept: false, reason: 'submission failed during suite execution' };
  }
  if (!Array.isArray(outputs) || outputs.length !== tests.length) {
    return { accept: false, reason: 'suite did not report every case' };
  }
  for (let i = 0; i < tests.length; i++) {
    if (!eq(outputs[i], expectedDedupe(tests[i]))) {
      return { accept: false, reason: 'incorrect result' };
    }
  }
  return { accept: true, reason: 'all pinned and property tests passed to completion' };
}

